<?php
require_once __DIR__.'/../app/helpers.php';require_auth();require_once __DIR__.'/../app/Services/NotificationService.php';$svc=new NotificationService(Database::connection());$uid=(int)auth_user()['id'];$events=['transfer_completed','transfer_failed','bill_payment_completed','card_payment_completed','atm_withdrawal_completed','risk_alert','kyc_status_changed'];$error=null;$success=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();foreach($events as $event){$svc->setPreference($uid,$event,isset($_POST['in_app'][$event]),isset($_POST['email'][$event]),isset($_POST['sms'][$event]));}$success='Notification preferences saved.';}catch(Throwable $e){$error=$e->getMessage();}}$existing=[];foreach($svc->preferences($uid) as $p)$existing[$p['event_type']]=$p;?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notification Preferences</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><h2 class="mb-4">Notification Preferences</h2><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="card shadow-sm border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Event</th><th>In-app</th><th>Email</th><th>SMS</th></tr></thead><tbody><?php foreach($events as $event):$p=$existing[$event]??['in_app_enabled'=>1,'email_enabled'=>1,'sms_enabled'=>0];?><tr><td><?=e(ucwords(str_replace('_',' ',$event)))?></td><td><input type="checkbox" name="in_app[<?=e($event)?>]" <?=((int)$p['in_app_enabled']?'checked':'')?>></td><td><input type="checkbox" name="email[<?=e($event)?>]" <?=((int)$p['email_enabled']?'checked':'')?>></td><td><input type="checkbox" name="sms[<?=e($event)?>]" <?=((int)$p['sms_enabled']?'checked':'')?>></td></tr><?php endforeach;?></tbody></table></div><div class="card-body"><button class="btn btn-primary">Save preferences</button> <a href="/commserve/public/dashboard.php" class="btn btn-link">Back</a></div></div></form></div></body></html>
